package com.rescuefarm.ui.engagement;
import com.rescuefarm.ui.common.EnumLabels;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import com.rescuefarm.R;import com.rescuefarm.domain.enums.*;import com.rescuefarm.domain.model.Report;import java.util.*;
public class AdminReportFragment extends Fragment{private final com.rescuefarm.ui.common.ListPagination pagination=new com.rescuefarm.ui.common.ListPagination();private EngagementViewModel vm;private LinearLayout box;@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_admin_reports,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){box=v.findViewById(R.id.adminReportContainer);vm=new ViewModelProvider(this,new EngagementViewModelFactory(requireContext())).get(EngagementViewModel.class);vm.reports().observe(getViewLifecycleOwner(),this::render);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==EngagementState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});vm.refreshReports();}private void render(List<Report>xs){pagination.render(box,xs,this::renderPage);}private void renderPage(List<Report>xs){box.removeAllViews();if(xs==null)return;for(Report r:xs){LinearLayout row=new LinearLayout(requireContext());row.setOrientation(LinearLayout.VERTICAL);TextView text=new TextView(requireContext());text.setText(getString(R.string.report_admin_row_format,EnumLabels.label(r.getTargetType()),r.getTargetId(),r.getReason(),EnumLabels.label(r.getStatus())));row.addView(text);if(r.getStatus()==ReportStatus.PENDING)row.addView(button(R.string.review_report_action,x->vm.transitionReport(r.getId(),ReportStatus.IN_REVIEW,"")));if(r.getStatus()==ReportStatus.IN_REVIEW){row.addView(button(R.string.resolve_report_action,x->vm.transitionReport(r.getId(),ReportStatus.RESOLVED,"Đã xử lý")));row.addView(button(R.string.reject_report_action,x->vm.transitionReport(r.getId(),ReportStatus.REJECTED,"Không vi phạm")));}box.addView(row);}}private Button button(int label,View.OnClickListener l){Button b=new Button(requireContext());b.setText(label);b.setOnClickListener(l);return b;}}
